pub struct SaveAsUseCase {
    uow_factory: Box<dyn SaveAsUnitOfWorkFactoryTrait>,
    dto: SaveAsDto,
}

impl SaveAsUseCase {
    pub fn new(uow_factory: Box<dyn SaveAsUnitOfWorkFactoryTrait>, dto: &SaveAsDto) -> Self {
        SaveAsUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for SaveAsUseCase {
    type Output = SaveAsResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        progress_callback(OperationProgress::new(0.0, Some("Saving…".to_string())));
        if self.dto.file_name.trim().is_empty() {
            return Err(anyhow!("a target .skrib path is required"));
        }

        let uow = self.uow_factory.create();
        uow.begin_transaction()?;
        let outcome = run_save_as(&*uow, &self.dto, &progress_callback, &cancel_flag);
        uow.end_transaction()?;

        let (work_id, result) = outcome?;
        uow.publish_save_as_event(vec![work_id], None);
        progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
        Ok(result)
    }
}

fn run_save_as(
    uow: &dyn SaveAsUnitOfWorkTrait,
    dto: &SaveAsDto,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, SaveAsResultDto)> {
    let forced = if dto.as_folder {
        SkribShape::ExplodedFolder
    } else {
        SkribShape::ZipFile
    };
    let g = work_io::gather(uow, dto.work_id as EntityId, progress, cancel)?;
    let (target, shape, tag) =
        work_io::resolve_target(&dto.file_name, g.work_info.as_ref(), Some(forced))?;
    let work_id = g.work.id;
    // The per-project media directory, resolved from where the project's bytes
    // are *now* — its current path — not from where this Save As is about to put
    // them. The destination does not exist yet, so it can never be recognised as
    // an exploded folder, and a folder project (whose images live in its own
    // `assets/` and are never copied to the uid-keyed directory) would resolve to
    // a directory that has never held a single one of its pictures: every image
    // and the cover would be dropped from the copy, silently, because a missing
    // file is a skip rather than an error. `backup_now` resolves from the source
    // for exactly this reason.
    //
    // A project that has never been saved has no source path; the destination is
    // then the honest answer, and the uid-keyed directory it resolves to is where
    // its images were put when they were inserted.
    let source = g
        .work_info
        .as_ref()
        .and_then(|wi| wi.file_name.clone())
        .unwrap_or_else(|| target.clone());
    let media_dir = skrib_format::media::media_dir(
        std::path::Path::new(&source),
        &g.work.unique_id,
        std::path::Path::new(&dto.media_root),
        &g.work.unique_id,
    );
    // Save As is a copy of the state already on disk, not a new edit: it carries
    // the source's history so the copy remembers as much as the original, and
    // records nothing so the act of copying never looks like a revision.
    let history = work_io::HistoryAction::Carry {
        source: source.clone(),
    };
    let output = work_io::serialize_and_write(
        &g,
        target,
        shape,
        tag,
        &media_dir,
        history,
        crate::lifecycle::SaveKind::SaveAs,
    )?;
    Ok((
        work_id,
        SaveAsResultDto {
            output_path: output,
        },
    ))
}
